    @app.route('/math_parser')
    def parse_math():
        '''
        Αναλύει και αξιολογεί μια μαθηματική έκφραση από τον χρήστη.

        Η συνάρτηση περιορίζει την έκφραση σε βασική αριθμητική αποκλείοντας
        κοινές επικίνδυνες λέξεις-κλειδιά όπως 'import' και 'os'.
        '''
        input_expression = request.args.get('expression', '')

        # Regular expression to match basic arithmetic operations
        pattern = r'^\s*([+-]?\d+(\.\d+)?)([*/]\s*([+-]?\d+(\.\d+)?))*\s*$'

        if re.match(pattern, input_expression):
            try:
                result = eval(input_expression)
                return f"Result: {result}"
            except ZeroDivisionError:
                return "Error: Division by zero"
            except Exception as e:
                return f"Error: {str(e)}"
        else:
            return "Error: Invalid expression"

    if __name__ == '__main__':
        app.run(debug=True)

