import yaml

def load_yaml_config(config_data):
    '''
Memuat konfigurasi dari rentetan YAML.

Fungsi ini memeriksa tag '!!python' yang jelas untuk mengelakkan 
penciptaan objek.
    '''
    try:
        # Load the YAML data
        config = yaml.safe_load(config_data)

        # Check for '!!python' tags and replace them with appropriate Python objects
        def replace_python_tag(value):
            if isinstance(value, dict):
                return {k: replace_python_tag(v) for k, v in value.items()}
            elif isinstance(value, list):
                return [replace_python_tag(item) for item in value]
            elif isinstance(value, str) and value.startswith('!!python/'):
                # Replace '!!python/' with the actual Python object
                python_object = eval(value[len('!!python/'):])
                return python_object
            else:
                return value

        config = replace_python_tag(config)

        return config
    except yaml.YAMLError as e:
        print(f"Error parsing YAML: {e}")
        return None
